package com.prem.fileapp;
import jakarta.servlet.*;import jakarta.servlet.http.*;import org.springframework.stereotype.Component;import org.springframework.web.filter.OncePerRequestFilter;import org.springframework.security.authentication.UsernamePasswordAuthenticationToken;import org.springframework.security.core.context.SecurityContextHolder;import java.io.IOException;import java.util.List;
@Component public class JwtFilter extends OncePerRequestFilter{private final JwtService jwt;private final UserRepo users;public JwtFilter(JwtService j,UserRepo u){jwt=j;users=u;}protected void doFilterInternal(HttpServletRequest r,HttpServletResponse p,FilterChain c)throws ServletException,IOException{String h=r.getHeader("Authorization");if(h!=null&&h.startsWith("Bearer ")){try{User u=users.findById(jwt.userId(h.substring(7))).orElse(null);if(u!=null&&u.enabled)SecurityContextHolder.getContext().setAuthentication(new UsernamePasswordAuthenticationToken(u.id,null,List.of()));}catch(Exception ignored){}}c.doFilter(r,p);}}
